steps.script:
var AIDM = load("res://scripts/AIDecisionMaker.gd")
AIDM.clear_all_plans()
AIDM._config_overrides["PLANS_ENABLED"] = 0
return str(AIDM.plans_enabled())

# Both seats AI, both on the Custodes list, and the deployment zone forced to
# the triangle. Start Game reads deployment_dropdown directly
# (MainMenu._on_start_button_pressed), which is what makes this reachable.
var m = tree.current_scene
var army = -1
for i in range(m.army_options.size()):
	if str(m.army_options[i].id) == "custodes_lions":
		army = i
var zone = -1
for i in range(m.deployment_options.size()):
	if str(m.deployment_options[i].id) == "crucible_of_battle":
		zone = i
if army < 0 or zone < 0:
	return "missing army=%d zone=%d" % [army, zone]
m.player1_dropdown.selected = army
m.player2_dropdown.selected = army
m.deployment_dropdown.selected = zone
for d in [m.player1_type_dropdown, m.player2_type_dropdown]:
	for i in range(d.item_count):
		if d.get_item_text(i) == "AI":
			d.selected = i
			d.emit_signal("item_selected", i)
return "%s|%s|%s|%s" % [str(m.army_options[army].id), str(m.deployment_options[zone].id), m.player1_type_dropdown.get_item_text(m.player1_type_dropdown.selected), m.player2_type_dropdown.get_item_text(m.player2_type_dropdown.selected)]

# The board really is the TRIANGLE, not a fixture's stale rectangle. Without
# this the rest of the scenario could pass on geometry that never had the
# defect — which is exactly what the first version of this test did.
var AIDM = load("res://scripts/AIDecisionMaker.gd")
var snap = {"board": GameState.state.get("board", {}), "meta": GameState.state.get("meta", {})}
var out = []
for player in [1, 2]:
	var poly = AIDM._get_deployment_zone_polygon_pixels(snap, player)
	var bounds = AIDM._get_deployment_zone_bounds(snap, player)
	var rect_area = (bounds.max_x - bounds.min_x) * (bounds.max_y - bounds.min_y)
	var poly_area = 0.0
	for i in range(poly.size()):
		var a = poly[i]
		var b = poly[(i + 1) % poly.size()]
		poly_area += a.x * b.y - b.x * a.y
	poly_area = abs(poly_area) * 0.5
	out.append(poly_area / max(1.0, rect_area))
print("SCENARIO pm_f1 zone: %s, polygon/rectangle area = %.2f, %.2f" % [str(GameState.state.meta.get("deployment_type", "?")), out[0], out[1]])
# A triangle fills about half its bounding box; a rectangle fills all of it.
return "%s|%s" % [str(GameState.state.meta.get("deployment_type", "?")), str(out[0] < 0.9 and out[1] < 0.9)]

var undeployed = 0
for uid in GameState.state.get("units", {}).keys():
	if int(GameState.state["units"][uid].get("status", 0)) == 0:
		undeployed += 1
print("SCENARIO pm_f1 undeployed at start: %d" % undeployed)
return undeployed > 0

# Deployment is done when nothing is left undeployed on either seat.
var undeployed = 0
for uid in GameState.state.get("units", {}).keys():
	if int(GameState.state["units"][uid].get("status", 0)) == 0:
		undeployed += 1
return undeployed == 0

# The claim. The formula may CHOOSE reserves; what it must not do is run out
# of legal placements and get dumped there, or burn retries getting rejected.
var failed = 0
var fallback = 0
for e in GameState.state.get("phase_log", []):
	var d = str(e.get("description", "")) + str(e.get("_ai_description", ""))
	if d.find("deployment failed") != -1:
		failed += 1
	if d.find("placed in reserves (fallback)") != -1 or d.find("placed in Strategic Reserves") != -1:
		fallback += 1
print("SCENARIO pm_f1 log: deployment_failed=%d reserves_fallback=%d" % [failed, fallback])
return "failed=%d fallback=%d" % [failed, fallback]
